  ["后像：幽灵体质"] = "Afterimage: Thể Chất U Linh",
  ["后像：异端信仰"] = "Afterimage: Tín Ngưỡng Dị Đoan",
  ["后像：拾荒者"] = "Afterimage: Kẻ Nhặt Nhạnh",
  ["后像：池中剑"] = "Afterimage: Kiếm Dưới Hồ",
